# =====================================================================

RARITY_INFO = {
    "common":    {"label": "⬜ Обычная",    "mult": 100, "weight": 50, "rank": 0},
    "uncommon":  {"label": "🟩 Необычная",  "mult": 105, "weight": 27, "rank": 1},
    "rare":      {"label": "🟦 Редкая",     "mult": 110, "weight": 15, "rank": 2},
    "epic":      {"label": "🟪 Эпическая",  "mult": 115, "weight": 6,  "rank": 3},
    "legendary": {"label": "🟨 Легендарная", "mult": 120, "weight": 2,  "rank": 4},
    # 🟧 ГЕРОИЧЕСКАЯ — редкость собственного персонажа игрока («🦸 Мой герой»).
    # weight=0: из «🎲 Получить карту» она НЕ выпадает никогда — герой
    # создаётся один раз через отдельный поток (класс + главная стата),
    # генерация = перебор ЭПИЧЕСКИХ карт (mult 115), пока выбранная стата
    # не победит в своей паре. Либо выдаётся админом вручную.
    "heroic":    {"label": "🟧 Героическая", "mult": 115, "weight": 0,  "rank": 5},
    # 🔴 АРКАНОВАЯ (правка заказчика): аркана — ЭТО РЕДКОСТЬ, обозначается
    # красным; бонусы статов — КАК У ЛЕГЕНДАРНОЙ (mult 120). weight=0:
    # выпадает только при включённой фиче feat_arcana (шанс ARCANA_CHANCE_PCT
    # при получении карты) или выдаётся админом. Каждая аркановая карта
    # дополнительно принадлежит одному из сетов (cards.arcana: 🔥 Пламя /
    # 🪨 Камень / 🌿 Жизнь) — связки на поле дают ауры (см. ARCANA_SETS).
    "arcana":    {"label": "🔴 Аркановая",  "mult": 120, "weight": 0,  "rank": 6},
}
RARITY_KEYS = list(RARITY_INFO.keys())

# ГАРАНТ (pity) — по заказу настраивается ПЕРЕМЕННОЙ: для каждой редкости
# число = сколько карт подряд «ниже этой редкости» гарантируют её выпадение;
# -1 = гаранта на эту редкость НЕТ. Сейчас гарант ОТКЛЮЧЁН на все редкости.
PITY_CONFIG = {
    "rare": -1,        # раньше было 40 — до отключения гаранта
    "epic": -1,
    "legendary": -1,
}

# =====================================================================
# 🦸 СОБСТВЕННЫЙ ПЕРСОНАЖ («Мой герой») — редкость «🟧 Героическая»
# =====================================================================
# Игрок ОДИН РАЗ создаёт личного героя:
#   1) выбирает КЛАСС (воин / заклинатель);
#   2) выбирает ГЛАВНУЮ СТАТУ — ровно одну из пар системы весов:
#        пара «Атака ↔ Защита»:  защита при сравнении ДЕЛИТСЯ НА 2 (//2);
#        пара «Здоровье ↔ Скрытность/Точность»: скрытность УМНОЖАЕТСЯ НА 4;
#      т.е. атака побеждает, если attack >= armor//2; здоровье побеждает,
#      если hp_max >= sub*4 (и наоборот — для защитных/скрытных билдов);
#   3) карта генерируется ПЕРЕБОРОМ персонажей ЭПИЧЕСКОЙ редкости, пока
#      выбранная стата не окажется большей в своей паре, и получает
#      редкость «heroic» (статы остаются эпическими — как заказано);
#   4) имя герою игрок может поменять СРАЗУ (бот спрашивает после
#      создания) и в любой момент потом (кнопка «✏️ Переименовать»).
# У заклинателя защита в паре с атакой не участвует (КЗ без перекоса и
# всегда проигрывает атаке) — поэтому магу защита не предлагается;
# его пары: Атака↔Запас Манны и Здоровье↔Точность.
HERO_MAIN_STATS = {
    CLS_WARRIOR: [("attack", "⚔️ Атака"), ("armor", "🛡 Защита"),
                  ("hp", "❤️ Здоровье"), ("sub", "🥷 Скрытность")],
    CLS_MAGE:    [("attack", "⚔️ Атака"), ("hp", "❤️ Здоровье"),
                  ("sub", "🎯 Точность")],
}
HERO_STAT_LABEL = {"attack": "⚔️ Атака", "armor": "🛡 Защита",
                   "hp": "❤️ Здоровье", "sub": "🥷 Скрытность / 🎯 Точность"}
HERO_REROLL_LIMIT = 500   # потолок перебора эпических персонажей (страховка)

# =====================================================================
# 🔴 АРКАНОВЫЕ ПЕРСОНАЖИ (экспериментальная фича — включается только
# в админ-панели, индивидуально каждому игроку: users.feat_arcana)
# =====================================================================
# АРКАНА — ЭТО РЕДКОСТЬ (правка заказчика): обозначается красным 🔴,
# бонусы статов — КАК У ЛЕГЕНДАРНОЙ карты (mult 120, см. RARITY_INFO).
# Каждая аркановая карта дополнительно принадлежит одному из СЕТОВ
# (cards.arcana). Когда на ПОЛЕ БОЯ одновременно стоит нужное число
# (need) карт одного сета — каждая получает постоянную ауру-бафф
# (снятие ауры — когда связка распалась, например союзник погиб).
# Шанс, что НОВАЯ карта окажется аркановой (только при включённой
# фиче) — ARCANA_CHANCE_PCT («очень редкие» — реже легендарной).
ARCANA_SETS = {
    "flame": {"name": "Пламя",    "emoji": "🔥", "need": 2, "fx": "arc_atk",
              "val": 2, "desc": "2+ карт сета на поле: +2 к Атаке каждой."},
    "stone": {"name": "Камень",   "emoji": "🪨", "need": 2, "fx": "arc_def",
              "val": 2, "desc": "2+ карт сета на поле: +2 к Защите (КЗ) каждой."},
    "life":  {"name": "Жизнь",    "emoji": "🌿", "need": 2, "fx": "arc_life",
              "val": 2, "desc": "2+ карт сета на поле: каждая лечит 2 HP в начале своего хода."},
}
ARCANA_KEYS = list(ARCANA_SETS.keys())
ARCANA_CHANCE_PCT = int(os.environ.get("ARCANA_CHANCE_PCT", "2") or 0)  # «пизда редкие»

# =====================================================================
# 🗡 АРТЕФАКТЫ (экспериментальная фича — включается только в админ-
# панели, индивидуально: users.feat_artifacts). Ресурс — 💎 осколки
# (users.shards), добываются в МИССИЯХ: отряд (боевая колода) уходит
# на вылазку, проводится бой с ботом, за ПОБЕДУ начисляются осколки.
# Артефакт надевается на карту (1 артефакт на карту, 1 карта у артефакта)
# и добавляет статы в бою; качается ОТДЕЛЬНО от карты за осколки.
# ВАЖНО: бонусы действуют только в бою и НЕ въедаются в БД карты —
# при записи итогов боя они вычитаются обратно (см. art_bonus).
#
# БАЛАНС (правка заказчика): прокачка до L10 РАСТЯНУТА от начального
# бонуса до максимума своей редкости — у каждой редкости свой КАП СИЛЫ
# (в поинтах), у легендарной и героической он максимальный:
#   ⬜10 · 🟩15 · 🟦20 · 🟪25 · 🟨30 · 🟧30 · 🥇30
# Текущий бонус = cap × ART_POWER_LEVELS[level-1] (кривая 0.33→1.00),
# округление ВНИЗ. В ПОИНТАХ статы весят по-разному (ART_STAT_WEIGHT):
# защита дороже атаки (каждое КЗ = −10% входящего урона), HP дешевле.
# Лимит суммарной силы отряда — переменная ART_DECK_POWER_LIMIT (0 = без
# лимита): надеть артефакты сверх бюджета нельзя.
# =====================================================================
ART_SLOTS = {"attack": "⚔️ Оружие", "armor": "🛡 Доспех",
             "hp": "❤️ Амулет жизни", "sub": "🥷 Клык тени"}

# КАП СИЛЫ артефакта (поинты на L10) — по редкости. Легендарная (и выше) —
# максимальная сила; более редкие = более «ёмкий» артефакт, но кривая та же.
ART_POWER_CAP = {
    "common": 10, "uncommon": 15, "rare": 20,
    "epic": 25, "legendary": 30, "heroic": 30, "arcana": 30,
}
# Кривая прокачки L1→L10: доля капа редкости на каждом уровне. Растяжка
# от начального бонуса (L1 = cap×0.33) до максимума (L10 = cap×1.00).
ART_POWER_LEVELS = (0.33, 0.40, 0.48, 0.55, 0.63, 0.70, 0.78, 0.85, 0.93, 1.00)
# Вес статы в ПОИНТАХ силы: 1 поинт = 1 ⚔️ = 2 ❤ = 0.6 🛡 = 0.8 🥷
# (защита в ~1.8 раза ценнее атаки, скрытность — в ~1.3 раза).
ART_STAT_WEIGHT = {"attack": 1.0, "armor": 1.8, "hp": 0.5, "sub": 1.3}
# Начальный бонус L1 — не меньше ART_MIN_BONUS (чтобы ⬜ артефакт был полезен)
ART_MIN_BONUS = 1
# ЛИМИТ СИЛЫ ОТРЯДА (поинты): суммарная сила надетых артефактов карт,
# идущих в бой. 0 = лимит выключен. Контролируется при надевании
# (экипировка сверх бюджета запрещена).
ART_DECK_POWER_LIMIT = int(os.environ.get("ART_DECK_POWER_LIMIT", "70") or 0)

ART_MAX_LEVEL = len(ART_POWER_LEVELS)     # = 10
ART_CRAFT_COST = 30          # 💎 за создание артефакта (стата — на выбор)
ART_UP_COST_STEP = 10        # 💎 улучшение: ART_UP_COST_STEP × текущий уровень
ART_NAMES = {
    "attack": ["Клинок Зари", "Секира Ярости", "Рунический Меч", "Пламенное Копьё",
               "Стальной Клык", "Гром Небесный", "Жнец Битв"],
    "armor":  ["Щит Стража", "Адамантовая Лата", "Руническая Броня", "Чешуя Дракона",
               "Покров Клятвы", "Бастион Веры", "Каменная Кожа"],
    "hp":     ["Рубиновое Сердце", "Амулет Жизни", "Чаша Жизни", "Слеза Феникса",
               "Кровь-Камень", "Сердце Матриарха", "Источник Сил"],
    "sub":    ["Плащ Теней", "Кинжал Убийцы", "Сапоги Тихого Шага", "Вуаль Сумрака",
               "Отравленный Шип", "Шёпот Ночи", "Маска Без Лица"],
}
# Миссии по добыче осколков: противник фиксированной редкости, его уровень =
# средний уровень вашей колоды + dlvl. Награда — только за ПОБЕДУ.
MISSIONS = [
    {"key": "e", "label": "🟢 Лёгкая вылазка",  "rar": "rare",      "dlvl": 0, "shards": 8},
    {"key": "n", "label": "🟡 Обычная вылазка", "rar": "epic",      "dlvl": 1, "shards": 15},
    {"key": "h", "label": "🔴 Тяжёлая вылазка", "rar": "legendary", "dlvl": 2, "shards": 30},
]


def art_up_cost(level: int) -> int:
    # Стоимость улучшения артефакта с уровня level до level+1 (в осколках)
    return ART_UP_COST_STEP * max(1, int(level))


def art_bonus_of(row) -> int:
    # Текущий бонус артефакта к его стате (в единицах статы).
    # БАЛАНС: сила = кап редкости (в ПОИНТАХ) × кривая уровня, округление
    # вниз; перевод поинтов в единицы статы — ДЕЛЕНИЕМ на вес статы
    # (🛡 защита «дорогая»: 30 п. = +16 КЗ; ❤ HP «дешёвое»: 30 п. = +60 HP;
    # 1 поинт = 1 ⚔ = 0.56 🛡 = 2 ❤ = 0.77 🥷). Минимум ART_MIN_BONUS —
    # даже ⬜ артефакт 1-го уровня что-то даёт.
    stat = row["stat"] if row.get("stat") in ART_STAT_WEIGHT else "attack"
    cap = ART_POWER_CAP.get(row.get("rarity") or "common", 10)
    lvl = max(1, min(int(row.get("level") or 1), ART_MAX_LEVEL))
    power = cap * ART_POWER_LEVELS[lvl - 1]          # поинты силы
    w = ART_STAT_WEIGHT.get(stat, 1.0)
    return max(ART_MIN_BONUS, int(power / w + 1e-9))


def artifact_power(row) -> float:
    # Сила артефакта В ПОИНТАХ (валюта баланса): бонус × вес статы.
    # Используется для лимита силы отряда (ART_DECK_POWER_LIMIT).
    stat = row["stat"] if row.get("stat") in ART_STAT_WEIGHT else "attack"
    return art_bonus_of(row) * ART_STAT_WEIGHT.get(stat, 1.0)


# =====================================================================
# ФОРМУЛЫ БОЯ — все коэффициенты собраны ЗДЕСЬ (правка заказчика).
# Урон больше не зашит целочисленной арифметикой в коде: переменные
# динамически подставляются в формулу
#     УРОН = АА × (1 + dmg_step × (попадание − КЗ)),
# где попадание — ПА обычной атаки или ПСА скрытой.
# dmg_step — та самая «0,1 перед скобкой разницы»: меняется в одном месте.
# =====================================================================
FORMULAS = {
    # Попадание атаки (ПА) = d20 + pa_base + pa_level × уровень (+ преимущество)
    "pa_base": 3,        # фиксированный бонус ПА
    "pa_level": 2,       # бонус ПА за каждый уровень юнита
    "adv": 2,            # бонус преимущества к ПА (атака при появлении, «Ускорение»)
    # Попадание скрытой атаки (ПСА) = d20 + psa_base + psa_level × уровень
    #                                  + psa_sub × (скрытность | точность)
    "psa_base": -3,      # фиксированный штраф ПСА
    "psa_level": 1,      # бонус ПСА за уровень
    "psa_sub": 2,        # бонус ПСА за очко скрытности/точности
    # Спасбросок от контроля = d20 + save_level × уровень ≥ DC
    "save_level": 1,
    # Множитель урона: (1 + dmg_step × разница), снизу ограничен dmg_min.
    "dmg_step": 0.1,     # шаг множителя за 1 пункт разницы (попадание − КЗ)
    "dmg_min": 0.0,      # пол: урон не бывает отрицательным
}

# ФЛАГ режима расчёта урона (правка заказчика):
#   "dynamic" — множитель (1 + dmg_step × разница) считается с плавающей
#               точностью: ПА чуть ниже КЗ УМЕНЬШАЕТ урон плавно (×0.9, ×0.5…),
#               а в ноль он уходит, только когда множитель стал ≤ 0
#               (при dmg_step = 0.1 — разница −10 и хуже);
#   "classic" — прежний целочисленный расчёт × (10 + разница) // 10:
#               ЛЮБОЕ попадание ниже КЗ сразу обнуляет урон.
DAMAGE_MODE = "dynamic"


def dmg_multiplier(diff: int, cap=None) -> float:
    # Множитель урона по формуле FORMULAS/DAMAGE_MODE.
    # diff = попадание − КЗ (для скрытой: ПСА − КЗ_заслона//2 − КЗ_цели),
    # cap  = потолок множителя (обычные/заклинания ×2, пробитие ×1;
    #        None — без потолка, как у скрытой атаки).
    if DAMAGE_MODE == "classic":
        m = float((10 + diff) // 10)              # старая целочисленная формула
    else:
        m = 1.0 + FORMULAS["dmg_step"] * diff     # АА × (1 + 0.1 × (ПА − КЗ))
    m = max(FORMULAS["dmg_min"], m)
    if cap is not None:
        m = min(float(cap), m)
    return m


def dmg_calc(base: int, mult: float) -> int:
    # УРОН = база (АА × coef_pct%) × множитель, округление ВНИЗ.
    # Добавка 1e-9 компенсирует погрешность двоичного представления
    # float (например, 1 + 0.1×(−6) = 0.3999999… вместо 0.4 — без неё
    # урон 10×0.4 посчитался бы как 3).
    return max(0, int(base * mult + 1e-9))



def rarity_rank(r: str) -> int:
    return RARITY_INFO.get(r, RARITY_INFO["common"])["rank"]


def rarity_label(r: str) -> str:
    return RARITY_INFO.get(r, RARITY_INFO["common"])["label"]

# =====================================================================
# КОЛОДЫ (до 3), ОТОБРАЖЕНИЕ КАРТ И СОРТИРОВКА КОЛЛЕКЦИИ
# =====================================================================

# Сколько колод может собрать игрок. cards.in_deck — БИТОВАЯ МАСКА (правка
# заказчика): бит колоды №n = 1 << (n−1), т.е. №1 = 1 (001), №2 = 2 (010),
# №3 = 4 (100); 0 = вне колод, 7 = карта сразу во всех трёх.
# ОДНА И ТА ЖЕ КАРТА МОЖЕТ ЛЕЖАТЬ В НЕСКОЛЬКИХ КОЛОДАХ ОДНОВРЕМЕННО.
# Старые данные: 1 и 2 уже совпадают с битами колод №1/№2, а старое
# «3 = колода №3» переносится в 4 миграцией v2.3 (см. migration_v2.sql).
DECK_COUNT = 3


def deck_bit(n: int) -> int:
    # Бит маски in_deck для колоды №n (нумерация с 1)
    return 1 << (max(1, min(int(n), DECK_COUNT)) - 1)


def card_decks(c) -> list:
    # Номера ВСЕХ колод, в которых лежит карта (маска in_deck)
    m = c["in_deck"] or 0
    return [n for n in range(1, DECK_COUNT + 1) if m & deck_bit(n)]


def decks_mark(c) -> str:
    # Значок карты для списков: «✅1·3» — в колодах №1 и №3, «🔸2» — только
    # в чужой колоде №2 (вызывается, когда в текущей её нет), «➖» — вне колод.
    ns = card_decks(c)
    return f"✅{'·'.join(str(n) for n in ns)}" if ns else "➖"

# С какого уровня можно даровать титул (кнопка в карточке коллекции)
TITLE_MIN_LEVEL = 3

# Критерии сортировки коллекции: (код, подпись). Код с «-» на конце —
# по убыванию. По умолчанию — 📅 дата получения (id, как раньше).
SORTS = [("id", "📅 Дата получения"), ("pwr", "💪 Главная стата"),
         ("rar", "✨ Редкость"), ("lvl", "⭐ Уровень"),
         ("atk", "⚔️ Атака"), ("def", "🛡 Защита"), ("hp", "❤️ Здоровье"),
         ("mna", "🔮 Запас манны"), ("end", "⚡ Выносливость"),
         ("sub", "🥷 Скрытность/🎯 Точность"), ("cls", "🧬 Класс"),
         ("rac", "🎭 Раса"), ("nm", "🔤 Имя")]

# Режим сборки колоды («🧩 Собрать колоду»): сортировка ПО УМОЛЧАНИЮ —
# от большего к меньшему (правка заказчика), по главной стате карты.
BUILDER_DEFAULT_SORT = "pwr-"
# f-параметр экрана сборки по умолчанию (фильтр «все» + сортировка выше)
BUILDER_DEFAULT_SORT_F = "all~" + BUILDER_DEFAULT_SORT


def sanitize_title(text: str) -> str:
    # Титул вводится игроком и попадает в HTML-сообщения — вырезаем
    # опасные символы и ограничиваем длину.
    return re.sub(r"[<>&]", "", text or "").strip()[:32]


def sanitize_nick(text: str) -> str:
    # Внутриигровой ник («👤 Профиль») — те же правила, что и для титула:
    # без HTML-спецсимволов (parse_mode=HTML глобальный), длина до 24.
    return re.sub(r"[<>&]", "", text or "").strip()[:24]


def sanitize_hero_name(text: str) -> str:
    # Имя собственного героя (🦸) — игрок вводит сразу при создании или
    # потом кнопкой «✏️ Переименовать». Правила как у титула: без «<>&»,
    # длина до 32. Заменяет связку «имя + фамилия» целиком.
    return re.sub(r"[<>&]", "", text or "").strip()[:32]


def disp_name(x, surname: bool = True) -> str:
    # Имя для показа: если карте дарован титул и включён режим
    # «использовать как имя» — титул идёт ПЕРВЫМ, затем настоящие
    # имя и фамилия: «Гроза Юга» Пупкин Васильев.
    # x — строка из БД или боевой юнит (dict).
    title = (x.get("title") or "").strip() if hasattr(x, "get") else ""
    base = x["name"] + (f" {x['surname']}" if surname and x.get("surname") else "")
    if title and x.get("use_title"):
        return f"«{title}» {base}"
    return base


def main_stat(cls: str, attack: int, armor: int):
    # Доминирующая стата (уточнение заказчика): у воинов — ПОБЕДИТЕЛЬ
    # сравнения «Атака vs Защита, делённая ЦЕЛО на два» (attack >= armor//2
    # → атака); у заклинателей — всегда атака. Возвращает (значок, число).
    if cls == CLS_MAGE:
        return "⚔", attack
    return ("⚔", attack) if attack >= armor // 2 else ("🛡", armor)


def arcana_mark(c) -> str:
    # 🌀 Значок сета аркановой карты (пусто для обычных). Работает и со
    # строками БД, и с боевыми юнитами.
    key = (c.get("arcana") or "") if hasattr(c, "get") else ""
    arc = ARCANA_SETS.get(key)
    return arc["emoji"] if arc else ""


def card_line(c) -> str:
    # Карта в одну строку (коллекция/колоды). Порядок по заказу:
    # класс, редкость, уровень, имя, атака или защита (что больше;
    # у магов всегда атака), здоровье у воинов / манна у заклинателей.
    rem = rarity_label(c.get("rarity") or "common").split(" ")[0]
    ico, val = main_stat(c["cls"], c["attack"], c["armor"])
    if c["cls"] == CLS_MAGE:
        res = f"🔮{c['mana_max']}"
    else:
        res = f"❤{c['hp']}" if c["hp"] >= c["hp_max"] else f"❤{c['hp']}/{c['hp_max']}"
    return (f"{CLS_EMOJI[c['cls']]}{arcana_mark(c)}{rem} L{c['level']} "
            f"{disp_name(c)} {ico}{val} {res}")


def card_full_line(c) -> str:
    # Карта СО ВСЕМИ статами одной строкой — для ТЕКСТА сообщений в
    # списках колод и коллекции (кнопки остаются компактными — card_line).
    rem = rarity_label(c.get("rarity") or "common").split(" ")[0]
    sub_e = "🥷" if c["cls"] == CLS_WARRIOR else "🎯"
    mana = f" · 🔮{c['mana_max']}" if c["cls"] == CLS_MAGE else ""
    return (f"{CLS_EMOJI[c['cls']]}{arcana_mark(c)}{rem} L{c['level']} {disp_name(c)} · "
            f"⚔{c['attack']} · 🛡{c['armor']} · ❤{c['hp']}/{c['hp_max']} · "
            f"{sub_e}{c['sub']} · ⚡{c['end_max']}{mana}")


def unit_line(u: dict) -> str:
    # Та же строка, но для боевого юнита (вкладка «Колода»/высадка):
    # ресурсы текущие, а при выносливости ≤1 вместо ❤/🔮 показывается
    # молния с остатком: ⚡1/4.
    ico, val = main_stat(u["cls"], u["attack"], u["armor"])
    if u["end"] <= 1:
        res = f"⚡{u['end']}/{u['end_max']}"
    elif u["cls"] == CLS_MAGE:
        res = f"🔮{u['mana']}"
    else:
        res = f"❤{u['hp']}"
    return f"{CLS_EMOJI[u['cls']]}{ico}{val} {res} {u['name']} L{u['level']}"


def sort_label(s: str) -> str:
    code = s[:-1] if s.endswith("-") else s
    for c, label in SORTS:
        if c == code:
            return label + (" 🔽" if s.endswith("-") else " 🔼")
    return "📅 Дата получения 🔼"


def sort_cards(cards, s: str):
    # s — код критерия из SORTS, «-» на конце = по убыванию.
    code = s[:-1] if s.endswith("-") else s
    desc = s.endswith("-")
    keyf = {
        "id":  lambda c: c["id"],
        "pwr": lambda c: main_stat(c["cls"], c["attack"], c["armor"])[1],
        "rar": lambda c: rarity_rank(c.get("rarity") or "common"),
        "lvl": lambda c: c["level"],
        "atk": lambda c: c["attack"],
        "def": lambda c: c["armor"],
        "hp":  lambda c: c["hp_max"],
        "mna": lambda c: c["mana_max"],
        "end": lambda c: c["end_max"],
        "sub": lambda c: c["sub"],
        "cls": lambda c: 0 if c["cls"] == CLS_WARRIOR else 1,
        "rac": lambda c: RACE_KEYS.index(c["race"]) if c["race"] in RACE_KEYS else 99,
        "nm":  lambda c: (c["name"] or "").lower(),
    }.get(code)
    if keyf is None:
        return list(cards)
    return sorted(cards, key=lambda c: (keyf(c), c["id"]), reverse=desc)


def decks_of(cards) -> dict:
    # Раскладывает карты по колодам {1: [...], 2: [...], 3: [...]}.
    # in_deck — битовая маска: одна карта может лежать в нескольких колодах,
    # тогда она попадёт в каждый соответствующий список.
    return {n: [c for c in cards if (c["in_deck"] or 0) & deck_bit(n)]
            for n in range(1, DECK_COUNT + 1)}

