@router.message(F.text)
async def msg_catchall(m: Message):
    # Единая точка входа для текста:
    #  1) нет доступа — любое сообщение трактуется как пароль;
    #  2) ждём админ-пароль (после /admin) — проверяем ADMIN_PASSWORD;
    #  3) иначе — показываем меню (заодно возвращаем пропавшую клавиатуру).
    await ensure_user(m.from_user.id, m.from_user.username)
    uid = m.from_user.id
    text = (m.text or "").strip()
    if not await has_access(uid):
        if text == ACCESS_PASSWORD:
            # Пароль верный — СРАЗУ отмечаем в БД, что доступ разрешён
            await grant_access(uid)
            await m.answer("✅ <b>Доступ разрешён!</b> Отметка сохранена в базе — "
                           "пароль больше вводить не нужно.\n\n" + MENU_TEXT,
                           reply_markup=KB_MENU)
        else:
            await set_user_flag(uid, "awaiting_password", 1)
            await m.answer("🔒 <b>Доступ ограничен.</b>\n\nВведите пароль:")
        return
    if await user_flag(uid, "awaiting_admin"):
        await set_user_flag(uid, "awaiting_admin", 0)
        if text == ADMIN_PASSWORD:
            await set_user_flag(uid, "is_admin", 1)
            await m.answer("🛠 <b>Админ-доступ разрешён.</b>\n\n" + admin_text(),
                           reply_markup=admin_kb())
        else:
            await m.answer("❌ Неверный админ-пароль.", reply_markup=KB_MENU)
        return
    if await user_flag(uid, "awaiting_feat"):
        # 🧪 Админ ввёл «Другому игроку (по ID)» — ждём числовой Telegram ID,
        # затем показываем экран индивидуальных фич этого игрока.
        if text.lower() in ("/cancel", "отмена"):
            await set_user_flag(uid, "awaiting_feat", 0)
            await m.answer("🧪 Ввод ID отменён.", reply_markup=KB_MENU)
            return
        if not text.isdigit():
            await m.answer("🧪 Нужен ЧИСЛОВОЙ Telegram ID игрока "
                           "(или /cancel для отмены).")
            return
        await set_user_flag(uid, "awaiting_feat", 0)
        target = int(text)
        await ensure_user_row(target)
        ftext, fmarkup = await feat_screen(target)
        await m.answer(ftext, reply_markup=fmarkup)
        return
    t_card = await user_flag(uid, "awaiting_title")
    if t_card:
        # Ждём текст титула для карты №t_card (кнопка «📜 Даровать титул»)
        if text.lower() in ("/cancel", "отмена"):
            await set_user_flag(uid, "awaiting_title", 0)
            await m.answer("📜 Ввод титула отменён.", reply_markup=KB_MENU)
            return
        title = sanitize_title(text)
        if not title:
            await m.answer("📜 Титул не может быть пустым (символы «&lt;» «&gt;» «&amp;» "
                           "не допускаются). Отправьте другой текст или /cancel.")
            return
        await db_set_title(int(t_card), title, uid)
        await set_user_flag(uid, "awaiting_title", 0)
        row = await db_get_card(int(t_card), uid)
        if row is None:
            await m.answer("Карта не найдена — титул не сохранён.", reply_markup=KB_MENU)
            return
        await m.answer(f"📜 Титул <b>«{title}»</b> дарован! Использовать его как имя — "
                       "переключатель 🎭 на карточке.\n\n" + card_text(row),
                       reply_markup=card_kb(row, "all", "0"))
        return
    h_card = await user_flag(uid, "awaiting_hero_name")
    if h_card:
        # Ждём новое имя ГЕРОЯ (🦸) — карта №h_card (🟧 heroic).
        # «/skip» и «пропустить» — оставить сгенерированное имя (шаг 3/3
        # создания героя); «/cancel» — отмена переименования.
        row = await db_get_card(int(h_card), uid)
        if text.lower() in ("/cancel", "отмена"):
            await set_user_flag(uid, "awaiting_hero_name", 0)
            if row:
                await m.answer("✏️ Переименование героя отменено.\n\n" + card_text(row),
                               reply_markup=card_kb(row, "all", "0"))
            else:
                await m.answer("✏️ Переименование отменено.", reply_markup=KB_MENU)
            return
        if text.lower() in ("/skip", "skip", "пропустить"):
            await set_user_flag(uid, "awaiting_hero_name", 0)
            if row:
                await m.answer("🦸 <b>Имя оставлено.</b> Герой готов — переименовать "
                               "можно в любой момент кнопкой «✏️ Переименовать».\n\n"
                               + card_text(row), reply_markup=card_kb(row, "all", "0"))
            else:
                await m.answer("🦸 Имя оставлено.", reply_markup=KB_MENU)
            return
        name = sanitize_hero_name(text)
        if not name:
            await m.answer("✏️ Имя не может быть пустым (символы «&lt;» «&gt;» «&amp;» "
                           "не допускаются). Отправьте другой текст, /skip или /cancel.")
            return
        if row is None or (row.get("rarity") or "common") != "heroic":
            await set_user_flag(uid, "awaiting_hero_name", 0)
            await m.answer("Карта героя не найдена — имя не сохранено.",
                           reply_markup=KB_MENU)
            return
        await db_rename_card(int(h_card), name, uid)
        await set_user_flag(uid, "awaiting_hero_name", 0)
        row = await db_get_card(int(h_card), uid)
        await m.answer(f"🦸 <b>Герой переименован: {name}!</b>\n\n" + card_text(row),
                       reply_markup=card_kb(row, "all", "0"))
        return
    if await user_flag(uid, "awaiting_nick"):
        # Ждём новый внутриигровой ник («👤 Профиль» → «✏️ Сменить ник»)
        if text.lower() in ("/cancel", "отмена"):
            await set_user_flag(uid, "awaiting_nick", 0)
            await m.answer("✏️ Смена ника отменена.", reply_markup=KB_MENU)
            return
        nick = sanitize_nick(text)
        if not nick:
            await m.answer("✏️ Ник не может быть пустым (символы «&lt;» «&gt;» «&amp;» "
                           "не допускаются). Отправьте другой текст или /cancel.")
            return
        await set_user_flag(uid, "awaiting_nick", 0)
        await db_set_nickname(uid, nick)
        ptext, pmarkup = await profile_screen(uid)
        await m.answer(f"✏️ Ник изменён на <b>{nick}</b>!\n\n{ptext}", reply_markup=pmarkup)
        return
    await m.answer(MENU_TEXT, reply_markup=KB_MENU)


@router.callback_query(F.data.startswith("hlp:"))
async def cb_help_page(call: CallbackQuery):
    # Листание страниц помощи (◀️/▶️): hlp:{номер страницы}
    n = call.data.split(":")[1]
    art, arc = await user_help_flags(call.from_user.id)
    text, markup = help_screen(int(n) if n.isdigit() else 0, art, arc)
    await safe_answer(call)
    await safe_edit(call, text, markup)


@router.callback_query(F.data == "mn:home")
async def cb_home(call: CallbackQuery):
    await safe_answer(call)
    await safe_edit(call, MENU_TEXT, None)


async def safe_answer(call, text=None, show_alert=False, cache_time=None):
    # answerCallbackQuery падает с «query is too old and response timeout
    # expired or query ID is invalid», если с момента нажатия кнопки прошло
    # ~10-15 секунд. Так бывает, когда Telegram повторно доставляет апдейт
    # после медленной или упавшей первой обработки (cold start, долгий бой,
    # прогон симуляций). Это НЕ повод ронять весь апдейт и пугать
    # пользователя «⚠️ Внутренняя ошибка бота»: молча глотаем именно эту
    # ошибку — хендлер доработает и обновит экран через safe_edit.
    try:
        await call.answer(text, show_alert=show_alert, cache_time=cache_time)
    except TelegramBadRequest as e:
        msg = str(e).lower()
        if "query is too old" in msg or "query id is invalid" in msg:
            return
        raise


def fit_text(text: str, limit: int = 4096) -> str:
    # Обрезка сообщения до лимита Telegram (страховка от «message is too
    # long»). Режем ПО ГРАНИЦЕ СТРОК: каждая строка экранов — законченный
    # HTML-блок, поэтому разметка не ломается.
    if len(text) <= limit:
        return text
    tail = "\n…(текст обрезан — уменьшите страницу/фильтр)"
    cut = text[:max(0, limit - len(tail))].rsplit("\n", 1)[0]
    return cut + tail


async def safe_edit(call: CallbackQuery, text: str, markup=None):
    # edit_text падает, если сообщение не изменилось или его его нельзя
    # редактировать — не считаем это ошибкой.
    # Важно: если передать reply_markup=None, Telegram оставит СТАРУЮ
    # клавиатуру, поэтому для «пустого» экрана явно шлём пустую клавиатуру.
    if markup is None:
        markup = InlineKeyboardMarkup(inline_keyboard=[])
    try:
        await call.message.edit_text(text, reply_markup=markup)
    except TelegramBadRequest as e:
        # Если Telegram не смог разобрать HTML-разметку (например, в текст
        # попал голый «<» или «&»), повторяем отправку БЕЗ parse_mode —
        # пользователь увидит простой текст вместо «залипшего» экрана.
        if "can't parse entities" in str(e):
            try:
                await call.message.edit_text(text, reply_markup=markup,
                                             parse_mode=None)
            except TelegramBadRequest:
                pass
        elif "message is too long" in str(e).lower():
            # Страховка от бага «Bad Request: message is too long»: режем
            # текст по границе строк и повторяем (см. fit_text).
            try:
                await call.message.edit_text(fit_text(text), reply_markup=markup)
            except TelegramBadRequest:
                pass
        # Остальные ошибки (сообщение не изменилось и т.п.) — игнорируем.


# =====================================================================
# ХЕНДЛЕРЫ: коллекция и боевая колода
# «📚 Коллекция» — ВСЕ карты (фильтры по классу/колоде/расе, сортировка,
# пагинация). «🃏 Колода» — просмотр колоды №1..3 + «🧩 Собрать колоду»:
# отдельный экран сборки (вверху состав колоды, внизу доступные карты
# со статами, фильтрами и сортировкой — по умолчанию от большего к
# меньшему). in_deck — битовая маска: одна карта может лежать в
# нескольких колодах сразу (см. deck_bit/card_decks и миграцию v2.3).
# =====================================================================

CARDS_PER_PAGE = 5

# Коды фильтров коллекции (участвуют в callback'ах, поэтому короткие):
#   all — все, w — воины, m — заклинатели, in — в колоде, out — вне колоды,
#   pend — 🌟 ожидают повышения (отложенные очки роста после матча),
#   q0..q4 — по редкости, r0..r9 — по расе (индекс в порядке RACES).
COL_FILTERS = [("all", "🧾 Все"), ("w", "⚔️ Воины"), ("m", "🔮 Заклинатели"),
               ("in", "✅ В колоде"), ("out", "➖ Вне колоды"),
               ("pend", "🌟 Ожидают повышения")]
RACE_KEYS = list(RACES.keys())


def col_filter_cards(cards, f: str):
    if f == "w":
        return [c for c in cards if c["cls"] == CLS_WARRIOR]
    if f == "m":
        return [c for c in cards if c["cls"] == CLS_MAGE]
    if f == "in":
        return [c for c in cards if c["in_deck"]]
    if f == "out":
        return [c for c in cards if not c["in_deck"]]
    if f == "pend":
        # 🌟 Ожидают повышения: карты с отложенными очками роста
        # (заработаны в матче, распределяются только ПОСЛЕ него).
        return [c for c in cards if (c.get("pending_levels") or 0) > 0]
    if f.startswith("q") and f[1:].isdigit() and int(f[1:]) < len(RARITY_KEYS):
        rk = RARITY_KEYS[int(f[1:])]
        return [c for c in cards if (c["rarity"] if "rarity" in c.keys() else "common") == rk]
    if f.startswith("r") and f[1:].isdigit() and int(f[1:]) < len(RACE_KEYS):
        race = RACE_KEYS[int(f[1:])]
        return [c for c in cards if c["race"] == race]
    return list(cards)


def col_filter_label(f: str) -> str:
    for code, label in COL_FILTERS:
        if code == f:
            return label
    if f.startswith("q") and f[1:].isdigit() and int(f[1:]) < len(RARITY_KEYS):
        return rarity_label(RARITY_KEYS[int(f[1:])])
    if f.startswith("r") and f[1:].isdigit() and int(f[1:]) < len(RACE_KEYS):
        race = RACE_KEYS[int(f[1:])]
        return f"{RACES[race]['emoji']} {race}"
    return "🧾 Все"


def card_text(row) -> str:
    sub_lbl = "🥷 Скрытность" if row["cls"] == CLS_WARRIOR else "🎯 Точность"
    mana_line = f"\n🔮 Запас манны: {row['mana_max']}" if row["cls"] == CLS_MAGE else ""
    ns = card_decks(row)
    in_deck_line = (f"✅ В колод{'ах' if len(ns) > 1 else 'е'}: "
                    f"{', '.join(f'№{n}' for n in ns)} — участвует в бою" if ns
                    else "➖ Вне колод — бой пропускает")
    rarity = row["rarity"] if "rarity" in row.keys() else "common"
    ttl = (row.get("title") or "").strip() if hasattr(row, "get") else ""
    title_line = ""
    if ttl:
        title_line = (f"\n📜 Титул: «{ttl}»" +
                      (" — используется как имя 🎭" if row.get("use_title") else
                       " (не используется как имя)"))
    pend = (row.get("pending_levels") or 0) if hasattr(row, "get") else 0
    pend_line = (f"\n🌟 Очков роста: {pend} — распределите кнопкой ниже "
                 "(прокачка только после матча)" if pend > 0 else "")
    hero_line = ""
    hm = (row.get("hero_main") or "") if hasattr(row, "get") else ""
    if hm in HERO_STAT_LABEL:
        hero_line = f"\n👑 Главная стата героя: {HERO_STAT_LABEL[hm]}"
    arc_line = ""
    arc = ARCANA_SETS.get((row.get("arcana") or "") if hasattr(row, "get") else "")
    if arc:
        arc_line = f"\n🌀 Аркана «{arc['name']}» {arc['emoji']}: {arc['desc']}"
    return "\n".join([
        f"🃏 <b>{disp_name(row)}</b> · #{row['id']}",
        f"{rarity_label(rarity)} · {RACES[row['race']]['emoji']} {row['race']} · {CLS_NAME[row['cls']]}",
        f"⭐ Уровень {row['level']} · Опыт {row['exp']}/{xp_to_next(row['level'])}"
        f"{hero_line}{title_line}{arc_line}{pend_line}",
        "",
        f"⚔️ Атака (АА): {row['attack']}",
        f"❤️ Здоровье: {row['hp']}/{row['hp_max']}",
        f"🛡 Защита (КЗ): {row['armor']}",
        f"{sub_lbl}: {row['sub']}",
        f"⚡ Выносливость: {row['end_max']}/{row['end_max']}{mana_line}",
        "",
        in_deck_line,
    ])


def card_kb(row, ctx: str, page: str) -> InlineKeyboardMarkup:
    # Кнопки карточки; «Назад» возвращает туда, откуда пришли (ctx+page).
    # Колоды — мультивыбор (карта может лежать в нескольких); титул — с L{TITLE_MIN_LEVEL}.
    cid = row["id"]
    ns = card_decks(row)
    cur = f" (сейчас {', '.join(f'№{n}' for n in ns)})" if ns else ""
    rows = [[ib(f"📥 В колоду…{cur}"[:64], f"dks:{cid}:{ctx}:{page}")],
            [ib("🗑 Сбросить карту", f"dkd:{cid}:{ctx}:{page}")]]
    # 🦸 Героя (🟧 heroic) можно переименовать в любой момент
    if ((row.get("rarity") if hasattr(row, "get") else row["rarity"]) or "common") == "heroic":
        rows.insert(0, [ib("✏️ Переименовать героя", f"hrn:{cid}:{ctx}:{page}")])
    pend = (row.get("pending_levels") or 0) if hasattr(row, "get") else 0
    if pend > 0:
        # Прокачка только после матча: отложенные очки распределяются здесь
        rows.insert(0, [ib(f"🌟 Распределить очки роста ({pend})", f"pls:{cid}:{ctx}:{page}")])
    ttl = (row.get("title") or "").strip() if hasattr(row, "get") else ""
    if row["level"] >= TITLE_MIN_LEVEL:
        if ttl:
            use = "используется как имя 🎭" if row.get("use_title") else "не используется как имя"
            rows.append([ib(f"🎭 «{ttl}» — {use}"[:64], f"tu:{cid}:{ctx}:{page}")])
            rows.append([ib("📜 Сменить титул", f"tt:{cid}:{ctx}:{page}")])
        else:
            rows.append([ib("📜 Даровать титул", f"tt:{cid}:{ctx}:{page}")])
    rows.append([ib("⬅️ Назад", back_cb(ctx, page))])
    return InlineKeyboardMarkup(inline_keyboard=rows)


def back_cb(ctx: str, page: str) -> str:
    # Куда ведёт «Назад»: dk — колоды, иначе коллекция с фильтром~сортировкой
    return "dk:1:0" if ctx == "dk" else f"col:{ctx}:{page}"


async def ctx_screen(user_id: int, ctx: str, page: str):
    # Экран по контексту возврата
    if ctx == "dk":
        return await deck_screen(user_id, 1, 0)
    return await collection_screen(user_id, ctx, int(page) if page.isdigit() else 0)


async def collection_screen(user_id: int, f: str, page: int):
    # «📚 Коллекция» — ВСЕ карты игрока с фильтром, сортировкой и пагинацией.
    # f = «<фильтр>» или «<фильтр>~<код_сортировки>» (коды — SORTS,
    # «-» на конце = по убыванию; пусто = 📅 дата получения, как раньше).
    flt, _, srt = f.partition("~")
    srt = srt or "id"
    cards = await db_user_cards(user_id)
    if not cards:
        return ("📚 <b>Коллекция пуста.</b>\n\nПолучите первую карту!",
                kb([ib("🎲 Получить карту", "getc")], [ib("🏠 Меню", "mn:home")]))
    deck_counts = [sum(1 for c in cards if (c["in_deck"] or 0) & deck_bit(n))
                   for n in range(1, DECK_COUNT + 1)]
    in_deck_n = sum(1 for c in cards if c["in_deck"])   # хотя бы в одной колоде
    decks_line = " ".join(f"{n}️⃣{deck_counts[n - 1]}" for n in range(1, DECK_COUNT + 1))
    pend_n = sum(1 for c in cards if (c.get("pending_levels") or 0) > 0)
    filt = sort_cards(col_filter_cards(cards, flt), srt)
    if not filt:
        return (f"📚 <b>Коллекция</b>: всего {len(cards)} карт · в колодах: {in_deck_n} ({decks_line})\n\n"
                f"Под фильтром «{col_filter_label(flt)}» карт нет.",
                kb([ib("🧾 Сбросить фильтр", f"col:all~{srt}:{page}")], [ib("🏠 Меню", "mn:home")]))
    n_pages = (len(filt) + CARDS_PER_PAGE - 1) // CARDS_PER_PAGE
    page = max(0, min(page, n_pages - 1))
    chunk = filt[page * CARDS_PER_PAGE:(page + 1) * CARDS_PER_PAGE]
    lines = [f"📚 <b>Коллекция</b>: всего {len(cards)} карт · в колодах: {in_deck_n} ({decks_line})"
             + (f" · 🌟 ждут повышения: {pend_n}" if pend_n else ""),
             f"Фильтр: {col_filter_label(flt)} · Сортировка: {sort_label(srt)} · показано {len(filt)}",
             f"В бой идут первые {MAX_DECK} карт каждой колоды.", ""]
    rows = []
    for c in chunk:
        mark = decks_mark(c)      # «✅1·3» — в колодах №1 и №3, «➖» — вне колод
        if (c.get("pending_levels") or 0) > 0:
            mark = "🌟" + mark      # карта ждёт распределения очков роста
        # В тексте сообщения — ВСЕ статы карты; на кнопке — компактно.
        lines.append(f"{mark} {card_full_line(c)}")
        rows.append([ib(f"{mark} {card_line(c)}"[:64], f"card:{c['id']}:{f}:{page}")])
    nav = []
    if page > 0:
        nav.append(ib("◀️", f"col:{f}:{page - 1}"))
    nav.append(ib("🎲 Получить карту", "getc"))
    if page < n_pages - 1:
        nav.append(ib("▶️", f"col:{f}:{page + 1}"))
    rows.append(nav)
    rows.append([ib(label, f"col:{code}~{srt}:{page}") for code, label in COL_FILTERS[:3]])
    rows.append([ib(label, f"col:{code}~{srt}:{page}") for code, label in COL_FILTERS[3:]])
    rows.append([ib("🎭 Раса", f"colr:{f}"), ib("✨ Редк.", f"colq:{f}"),
                 ib("🔃 Сортировка", f"srt:{f}:{page}")])
    rows.append([ib("🃏 Колоды", "dk:1:0"), ib("🏠 Меню", "mn:home")])
    return "\n".join(lines), InlineKeyboardMarkup(inline_keyboard=rows)


async def deck_screen(user_id: int, deck: int = 1, page: int = 0):
    # «🃏 Колоды» — ПРОСМОТР колоды №deck: состав с полными статами,
    # вкладки 1..DECK_COUNT, ⭐приоритет и кнопка «🧩 Собрать колоду»
    # (правка заказчика: сборка вынесена на отдельный экран —
    # deck_builder_screen; коллекция отсюда больше не открывается).
    deck = max(1, min(int(deck), DECK_COUNT))
    cards = await db_user_cards(user_id)
    if not cards:
        return ("🃏 <b>Карт пока нет.</b>\n\nПолучите первую карту — и добавьте её в колоду.",
                kb([ib("🎲 Получить карту", "getc")], [ib("🏠 Меню", "mn:home")]))
    pref = await user_flag(user_id, "pref_deck")
    decks = decks_of(cards)
    in_deck = decks[deck]
    star = " · ⭐ приоритетная" if pref == deck else ""
    lines = [f"🃏 <b>Колода №{deck}</b>: {len(in_deck)} карт{star}", ""]
    if in_deck:
        if len(in_deck) > MAX_DECK:
            lines.append(f"⚠️ Карт больше {MAX_DECK} — в бой пойдут только первые {MAX_DECK} (⚔️).")
        for i, c in enumerate(in_deck):
            mark = "⚔️" if i < MAX_DECK else "▪️"
            others = [n for n in card_decks(c) if n != deck]
            also = (f" <i>(ещё в {'·'.join(f'№{n}' for n in others)})</i>" if others else "")
            lines.append(f"{mark} {card_full_line(c)}{also}")
    else:
        lines.append("Колода пуста — нажмите «🧩 Собрать колоду» и выберите карты.")
    lines += ["", f"В бой идут первые {MAX_DECK} карт колоды.",
              "Одна и та же карта может лежать в нескольких колодах сразу."]
    rows = []
    tabs = []
    for n in range(1, DECK_COUNT + 1):
        cur = "🔹" if n == deck else ""
        star_n = "⭐" if pref == n else ""
        tabs.append(ib(f"{cur}{n}️⃣{star_n}·{len(decks[n])}", f"dk:{n}:0"))
    rows.append(tabs)
    rows.append([ib("🧩 Собрать колоду", f"dkb:{deck}:{BUILDER_DEFAULT_SORT_F}:0")])
    rows.append([ib("⭐ Сделать приоритетной" if pref != deck else "⭐ Убрать приоритет",
                    f"pdk:{deck}")])
    rows.append([ib("🏠 Меню", "mn:home")])
    return "\n".join(lines), InlineKeyboardMarkup(inline_keyboard=rows)


async def deck_builder_screen(user_id: int, deck: int, f: str, page: int):
    # «🧩 Собрать колоду» — экран сборки колоды №deck (правка заказчика):
    #  • ВВЕРХУ сообщения — карты, которые УЖЕ добавлены в эту колоду;
    #  • ВНИЗУ — какие карты с какими статами сейчас выводятся: отфильтрованный
    #    список ВСЕЙ коллекции (нажатие на кнопку = добавить/убрать из ЭТОЙ
    #    колоды; другие колоды карты не затрагиваются — in_deck битовая маска);
    #  • фильтрация как в коллекции, сортировка ПО УМОЛЧАНИЮ — от большего
    #    к меньшему (BUILDER_DEFAULT_SORT = «pwr-», 💪 главная стата 🔽).
    # f = «<фильтр>» или «<фильтр>~<код_сортировки>» (коды — SORTS).
    deck = max(1, min(int(deck), DECK_COUNT))
    flt, _, srt = f.partition("~")
    srt = srt or BUILDER_DEFAULT_SORT
    cards = await db_user_cards(user_id)
    if not cards:
        return ("🃏 <b>Карт пока нет.</b>\n\nПолучите первую карту — и добавьте её в колоду.",
                kb([ib("🎲 Получить карту", "getc")], [ib("🏠 Меню", "mn:home")]))
    bit = deck_bit(deck)
    in_deck = [c for c in cards if (c["in_deck"] or 0) & bit]
    lines = [f"🧩 <b>Сбор колоды №{deck}</b>: {len(in_deck)} карт", ""]
    if len(in_deck) > MAX_DECK:
        lines.append(f"⚠️ Больше {MAX_DECK} карт — в бой пойдут только первые {MAX_DECK} (⚔️).")
    lines.append("<b>Уже в колоде:</b>")
    if in_deck:
        for i, c in enumerate(in_deck):
            mark = "⚔️" if i < MAX_DECK else "▪️"
            lines.append(f"{mark} {card_full_line(c)}")
    else:
        lines.append("(пусто — выберите карты внизу)")
    filt = sort_cards(col_filter_cards(cards, flt), srt)
    lines += ["",
              f"<b>Доступные карты</b> · Фильтр: {col_filter_label(flt)} · "
              f"Сортировка: {sort_label(srt)}",
              f"(нажатие на карту = добавить в колоду №{deck} / убрать из неё):"]
    if not filt:
        lines.append(f"Под фильтром «{col_filter_label(flt)}» карт нет.")
    n_pages = max(1, (len(filt) + CARDS_PER_PAGE - 1) // CARDS_PER_PAGE)
    page = max(0, min(int(page), n_pages - 1))
    rows = []
    for c in filt[page * CARDS_PER_PAGE:(page + 1) * CARDS_PER_PAGE]:
        m = c["in_deck"] or 0
        if m & bit:
            # в этой колоде (✅) + возможно ещё в чужих (🔸номера)
            others = [n for n in card_decks(c) if n != deck]
            mark = "✅" + (f"🔸{'·'.join(str(n) for n in others)}" if others else "")
        elif m:
            mark = f"🔸{'·'.join(str(n) for n in card_decks(c))}"   # только в других
        else:
            mark = "➖"
        # В тексте сообщения — ВСЕ статы карты; на кнопке — компактно.
        lines.append(f"{mark} {card_full_line(c)}")
        rows.append([ib(f"{mark} {card_line(c)}"[:64], f"dkg:{c['id']}:{deck}:{f}:{page}")])
    nav = []
    if page > 0:
        nav.append(ib("◀️", f"dkb:{deck}:{f}:{page - 1}"))
    if page < n_pages - 1:
        nav.append(ib("▶️", f"dkb:{deck}:{f}:{page + 1}"))
    if nav:
        rows.append(nav)
    rows.append([ib(label, f"dkb:{deck}:{code}~{srt}:{page}") for code, label in COL_FILTERS[:3]])
    rows.append([ib(label, f"dkb:{deck}:{code}~{srt}:{page}") for code, label in COL_FILTERS[3:]])
    rows.append([ib("🎭 Раса", f"dkbr:{deck}:{f}:{page}"),
                 ib("✨ Редк.", f"dkbq:{deck}:{f}:{page}"),
                 ib("🔃 Сортировка", f"dkbs:{deck}:{f}:{page}")])
    rows.append([ib(f"🃏 Колода №{deck}", f"dk:{deck}:0"), ib("🏠 Меню", "mn:home")])
    return "\n".join(lines), InlineKeyboardMarkup(inline_keyboard=rows)


