# =====================================================================
# 🗡 АРТЕФАКТЫ И ⛏ МИССИИ ПО ДОБЫЧЕ (экспериментальная фича)
# =====================================================================
# Включается ТОЛЬКО в админ-панели и ИНДИВИДУАЛЬНО (users.feat_artifacts).
# План реализации — Optim1=Help;Hero;TimeOut.md, раздел «Артефакты».
#
# Цикл: ⛏ миссия (бой отряда с ботом повышенной сложности) → 💎 осколки
#       за победу → 🧿 создание / ⬆️ улучшение артефактов → 🃏 надеть на
#       карту → бонус к статам в следующем бою.
# Ограничения: 1 артефакт на карту, 1 карта у артефакта; бонусы живут
# только в бою и вычитаются при записи итогов в БД (см. art_bonus /
# db_sync_card_after_battle) — карта не «впитывает» артефакт навсегда.
# =====================================================================

ARTS_PER_PAGE = 8
ART_STAT_ICON = {"attack": "⚔️", "armor": "🛡", "hp": "❤️", "sub": "🥷"}


async def _art_ok(call: CallbackQuery) -> bool:
    # Страж фичи: артефакты доступны только с флагом из админ-панели
    if not await user_flag(call.from_user.id, "feat_artifacts"):
        await safe_answer(call, "🗡 Артефакты — экспериментальная функция. "
                                "Её включает админ индивидуально (админ-панель "
                                "→ «🧪 Фичи»).", show_alert=True)
        return False
    return True


def artifact_line(a, cards=None) -> str:
    # Артефакт в одну строку (список/детали): бонус к стате + сила в поинтах
    stat = a["stat"] if a.get("stat") in ART_STAT_WEIGHT else "attack"
    ico = ART_STAT_ICON.get(stat, "•")
    rem = rarity_label(a.get("rarity") or "common").split(" ")[0]
    eq = ""
    cid = a.get("equipped_card") or 0
    if cid and cards:
        c = next((x for x in cards if x["id"] == cid), None)
        if c:
            eq = f" → {disp_name(c)}"
    return (f"{ico} {a['name']} {rem} L{a.get('level') or 1} "
            f"(+{art_bonus_of(a)} · {artifact_power(a):g}п){eq}")


async def artifacts_screen(user_id: int, page: int = 0):
    # «🗡 Артефакты»: баланс осколков, список артефактов (пагинация),
    # создание и вход в миссии.
    fl = await db_get_flags(user_id)
    shards = fl.get("shards") or 0
    arts = await db_user_artifacts(user_id)
    cards = await db_user_cards(user_id)
    lines = [f"🗡 <b>Артефакты</b> · 💎 осколков: <b>{shards}</b>", ""]
    rows = []
    if arts:
        n_pages = max(1, (len(arts) + ARTS_PER_PAGE - 1) // ARTS_PER_PAGE)
        page = max(0, min(int(page), n_pages - 1))
        lines.append("Ваши артефакты (нажмите — улучшить/надеть):")
        for a in arts[page * ARTS_PER_PAGE:(page + 1) * ARTS_PER_PAGE]:
            lines.append("• " + artifact_line(a, cards))
            rows.append([ib(artifact_line(a)[:64], f"arta:{a['id']}:{page}")])
        nav = []
        if page > 0:
            nav.append(ib("◀️", f"art:{page - 1}"))
        if page < n_pages - 1:
            nav.append(ib("▶️", f"art:{page + 1}"))
        if nav:
            rows.append(nav)
    else:
        page = 0
        lines.append("Артефактов пока нет — создайте первый за осколки "
                     f"(💎{shards}/{ART_CRAFT_COST}) или добудьте осколки в миссии.")
    rows.append([ib(f"🧿 Создать артефакт ({ART_CRAFT_COST}💎)", "artcraft"),
                 ib("⛏ Миссия по добыче", "artm")])
    rows.append([ib("👤 Профиль", "prof"), ib("🏠 Меню", "mn:home")])
    return "\n".join(lines), InlineKeyboardMarkup(inline_keyboard=rows)


@router.callback_query(F.data.startswith("art:"))
async def cb_artifacts(call: CallbackQuery):
    if not await _art_ok(call):
        return
    page = call.data.split(":")[1]
    text, markup = await artifacts_screen(call.from_user.id,
                                          int(page) if page.isdigit() else 0)
    await safe_answer(call)
    await safe_edit(call, text, markup)


@router.callback_query(F.data == "artcraft")
async def cb_art_craft_menu(call: CallbackQuery):
    # 🧿 Создание: выбор статы артефакта (редкость и имя — случайные)
    if not await _art_ok(call):
        return
    fl = await db_get_flags(call.from_user.id)
    shards = fl.get("shards") or 0
    rows = []
    for s in ART_SLOTS:
        lo = art_bonus_of({"stat": s, "rarity": "common", "level": 1})
        hi = art_bonus_of({"stat": s, "rarity": "legendary", "level": ART_MAX_LEVEL})
        rows.append([ib(f"{ART_SLOTS[s]} — от +{lo} до +{hi}", f"artcraft:{s}")])
    rows.append([ib("⬅️ Назад", "art:0")])
    await safe_answer(call)
    await safe_edit(call, f"🧿 <b>Создание артефакта</b> · стоимость: {ART_CRAFT_COST}💎 "
                          f"(у вас 💎{shards})\n\nРедкость будет случайной — она задаёт "
                          "<b>потолок силы</b> (в поинтах): ⬜10 · 🟩15 · 🟦20 · 🟪25 · "
                          "🟨30. Прокачка L1→L10 раскрывает его: 33% → 100%. "
                          "Чем реже артефакт, тем сильнее вырастет. Выберите стату:",
                    InlineKeyboardMarkup(inline_keyboard=rows))


@router.callback_query(F.data.startswith("artcraft:"))
async def cb_art_craft_do(call: CallbackQuery):
    if not await _art_ok(call):
        return
    stat = call.data.split(":")[1]
    uid = call.from_user.id
    if stat not in ART_STAT_WEIGHT:
        await safe_answer(call, "Неизвестная стата.", show_alert=True)
        return
    fl = await db_get_flags(uid)
    shards = fl.get("shards") or 0
    if shards < ART_CRAFT_COST:
        await safe_answer(call, f"Недостаточно осколков: нужно {ART_CRAFT_COST}💎, "
                                f"у вас {shards}💎. Добудьте в миссии (⛏).",
                          show_alert=True)
        return
    await db_add_shards(uid, -ART_CRAFT_COST)
    d = {"name": random.choice(ART_NAMES[stat]), "stat": stat,
         "rarity": roll_rarity(), "level": 1}
    aid = await db_add_artifact(uid, d)
    row = await db_get_artifact(aid, uid)
    await safe_answer(call, "🧿 Артефакт создан!")
    if row is None:
        text, markup = await artifacts_screen(uid, 0)
        await safe_edit(call, text, markup)
        return
    await safe_edit(call, "🧿 <b>Артефакт создан!</b>\n\n" + artifact_line(row) +
                    "\n\nНаденьте его на карту — бонус действует в бою.",
                    kb([ib("🃏 Надеть на карту…", f"arte:{aid}:0")],
                       [ib("⬆️ Улучшить", f"artu:{aid}:0"), ib("🗡 Артефакты", "art:0")]))


@router.callback_query(F.data.startswith("arta:"))
async def cb_artifact_details(call: CallbackQuery):
    # Карточка артефакта: бонус, уровень, надетая карта, действия
    if not await _art_ok(call):
        return
    parts = call.data.split(":")
    aid, page = int(parts[1]), parts[2] if len(parts) > 2 else "0"
    uid = call.from_user.id
    row = await db_get_artifact(aid, uid)
    if not row:
        await safe_answer(call, "Артефакт не найден.", show_alert=True)
        return
    cards = await db_user_cards(uid)
    stat = row["stat"] if row.get("stat") in ART_STAT_WEIGHT else "attack"
    lvl = max(1, int(row.get("level") or 1))
    rar = row.get("rarity") or "common"
    cap = ART_POWER_CAP.get(rar, 10)
    bonus = art_bonus_of(row)
    power = artifact_power(row)
    cid = row.get("equipped_card") or 0
    eq_c = next((c for c in cards if c["id"] == cid), None) if cid else None
    eq = f"🃏 Надет на: <b>{disp_name(eq_c)}</b>" if eq_c else "🃏 Не надет"
    pct = int(round(ART_POWER_LEVELS[lvl - 1] * 100))
    if lvl < ART_MAX_LEVEL:
        nxt = art_bonus_of({**row, "level": lvl + 1})
        up_line = f"⬆️ Следующий уровень: {art_up_cost(lvl)}💎 → бонус +{nxt}"
    else:
        up_line = "⭐ Максимальный уровень — потолок силы раскрыт"
    text = (f"🗡 <b>{row['name']}</b> · #{row['id']}\n"
            f"{rarity_label(rar)} · {ART_SLOTS.get(stat, stat)}\n\n"
            f"{ART_STAT_ICON[stat]} Бонус в бою: <b>+{bonus}</b> к стате\n"
            f"💪 Сила: <b>{power:g}/{cap}</b> поинтов ({pct}% потолка — "
            f"{lvl}-й уровень)\n"
            f"⭐ Уровень: {lvl}/{ART_MAX_LEVEL} · {up_line}\n{eq}\n\n"
            f"<i>Потолок силы задаёт редкость (🟨 макс.). Бонус действует "
            f"только в бою и не въедается в карту — снять можно в любой "
            f"момент. Сила отряда ограничена: {ART_DECK_POWER_LIMIT or '∞'} "
            f"поинтов на колоду.</i>")
    rows = []
    if lvl < ART_MAX_LEVEL:
        rows.append([ib(f"⬆️ Улучшить ({art_up_cost(lvl)}💎)", f"artu:{aid}:{page}")])
    rows.append([ib("🃏 Надеть на карту…" if not eq_c else "🃏 Надеть на другую…",
                    f"arte:{aid}:{page}")])
    if eq_c:
        rows.append([ib("♻️ Снять", f"artoff:{aid}:{page}")])
    rows.append([ib("⬅️ К списку", f"art:{page}")])
    await safe_answer(call)
    await safe_edit(call, text, InlineKeyboardMarkup(inline_keyboard=rows))


@router.callback_query(F.data.startswith("artu:"))
async def cb_artifact_upgrade(call: CallbackQuery):
    # ⬆️ Улучшение за осколки: цена = ART_UP_COST_STEP × уровень
    if not await _art_ok(call):
        return
    parts = call.data.split(":")
    aid, page = int(parts[1]), parts[2] if len(parts) > 2 else "0"
    uid = call.from_user.id
    row = await db_get_artifact(aid, uid)
    if not row:
        await safe_answer(call, "Артефакт не найден.", show_alert=True)
        return
    lvl = max(1, int(row.get("level") or 1))
    if lvl >= ART_MAX_LEVEL:
        await safe_answer(call, f"Уже максимальный уровень ({ART_MAX_LEVEL}).",
                          show_alert=True)
        return
    cost = art_up_cost(lvl)
    fl = await db_get_flags(uid)
    if (fl.get("shards") or 0) < cost:
        await safe_answer(call, f"Нужно {cost}💎, у вас {fl.get('shards') or 0}💎. "
                                "Добудьте в миссии (⛏).", show_alert=True)
        return
    await db_add_shards(uid, -cost)
    await db_patch_artifact(aid, uid, {"level": lvl + 1})
    row = await db_get_artifact(aid, uid)
    await safe_answer(call, f"⬆️ Уровень {lvl + 1}!")
    stat = row["stat"] if row.get("stat") in ART_STAT_WEIGHT else "attack"
    await safe_edit(call, f"⬆️ <b>{row['name']}</b> улучшен до L{lvl + 1} — "
                          f"бонус теперь {ART_STAT_ICON[stat]}+{art_bonus_of(row)}.\n"
                          f"💎 Осколков: {(fl.get('shards') or 0) - cost}",
                    kb([ib("⬆️ Улучшить ещё", f"artu:{aid}:{page}")
                        if lvl + 1 < ART_MAX_LEVEL else ib("⭐ Макс. уровень", f"arta:{aid}:{page}")],
                       [ib("🗡 К артефакту", f"arta:{aid}:{page}"), ib("🗡 Список", f"art:{page}")]))


@router.callback_query(F.data.startswith("arte:"))
async def cb_artifact_equip_list(call: CallbackQuery):
    # 🃏 Надеть: список карт коллекции (пагинация), клик — надеть
    if not await _art_ok(call):
        return
    parts = call.data.split(":")
    aid = int(parts[1])
    uid = call.from_user.id
    row = await db_get_artifact(aid, uid)
    if not row:
        await safe_answer(call, "Артефакт не найден.", show_alert=True)
        return
    cards = await db_user_cards(uid)
    if not cards:
        await safe_answer(call, "Нет карт — не на что надеть.", show_alert=True)
        return
    page = int(parts[2]) if len(parts) > 2 and parts[2].isdigit() else 0
    n_pages = max(1, (len(cards) + CARDS_PER_PAGE - 1) // CARDS_PER_PAGE)
    page = max(0, min(page, n_pages - 1))
    cur = row.get("equipped_card") or 0
    rows = []
    lines = [f"🃏 <b>Надеть «{row['name']}»</b> — выберите карту "
             f"(сейчас: {'⬇️ ниже' if cur else 'не надет'}):"]
    for c in cards[page * CARDS_PER_PAGE:(page + 1) * CARDS_PER_PAGE]:
        mark = "✅ " if c["id"] == cur else ""
        lines.append(f"{mark}{card_full_line(c)}")
        rows.append([ib(f"{mark}{card_line(c)}"[:64], f"arteq:{aid}:{c['id']}:{page}")])
    nav = []
    if page > 0:
        nav.append(ib("◀️", f"arte:{aid}:{page - 1}"))
    nav.append(ib("⬅️ К артефакту", f"arta:{aid}:0"))
    if page < n_pages - 1:
        nav.append(ib("▶️", f"arte:{aid}:{page + 1}"))
    rows.append(nav)
    await safe_answer(call)
    await safe_edit(call, "\n".join(lines), InlineKeyboardMarkup(inline_keyboard=rows))


@router.callback_query(F.data.startswith("arteq:"))
async def cb_artifact_equip(call: CallbackQuery):
    if not await _art_ok(call):
        return
    _, aid, cid, page = call.data.split(":")
    uid = call.from_user.id
    row = await db_get_artifact(int(aid), uid)
    card = await db_get_card(int(cid), uid)
    if not row or not card:
        await safe_answer(call, "Артефакт или карта не найдены.", show_alert=True)
        return
    # ⚖️ Лимит силы отряда (ART_DECK_POWER_LIMIT, поинты): проверяем все
    # колоды, где карта входит в боевой состав (первые MAX_DECK). Старый
    # артефакт карты в расчёт не берётся — его слот освобождается.
    if ART_DECK_POWER_LIMIT > 0:
        all_cards = await db_user_cards(uid)
        arts = await db_user_artifacts(uid)
        pow_of = {int(a["equipped_card"]): artifact_power(a)
                  for a in arts if a.get("equipped_card") and a["id"] != row["id"]}
        for n, dcards in decks_of(all_cards).items():
            battle = dcards[:MAX_DECK]
            if not any(c["id"] == card["id"] for c in battle):
                continue
            total = sum(pow_of.get(int(c["id"]), 0.0) for c in battle
                        if c["id"] != card["id"])
            if total + artifact_power(row) > ART_DECK_POWER_LIMIT + 1e-9:
                await safe_answer(
                    call, f"⚖️ Превышен лимит силы отряда ({ART_DECK_POWER_LIMIT:g} п.): "
                          f"колода №{n} уже несёт {total:g} п., артефакт добавляет "
                          f"{artifact_power(row):g} п. Снимите что-нибудь или "
                          f"улучшайте менее «тяжёлые» артефакты.", show_alert=True)
                return
    # На карте может быть только ОДИН артефакт — освобождаем слот
    await db_unequip_card(uid, int(cid))
    await db_patch_artifact(int(aid), uid, {"equipped_card": int(cid)})
    row = await db_get_artifact(int(aid), uid)
    await safe_answer(call, "🃏 Артефакт надет!")
    await safe_edit(call, f"🗡 <b>{row['name']}</b> надет на {disp_name(card)} — "
                          f"бонус действует в следующем бою (в текущем активном бою "
                          "состав уже зафиксирован).\n\n" + card_text(card),
                    kb([ib("🗡 Артефакты", f"art:{page}")], [ib("🏠 Меню", "mn:home")]))


@router.callback_query(F.data.startswith("artoff:"))
async def cb_artifact_unequip(call: CallbackQuery):
    if not await _art_ok(call):
        return
    parts = call.data.split(":")
    aid, page = int(parts[1]), parts[2] if len(parts) > 2 else "0"
    uid = call.from_user.id
    row = await db_get_artifact(aid, uid)
    if not row:
        await safe_answer(call, "Артефакт не найден.", show_alert=True)
        return
    await db_patch_artifact(aid, uid, {"equipped_card": 0})
    row = await db_get_artifact(aid, uid)
    await safe_answer(call, "♻️ Артефакт снят")
    await safe_edit(call, f"♻️ <b>{row['name']}</b> снят — статы карты снова базовые.",
                    kb([ib("🗡 К артефакту", f"arta:{aid}:{page}")],
                       [ib("🗡 Список", f"art:{page}")]))


# ---------- ⛏ миссии по добыче осколков ----------

async def missions_screen(user_id: int):
    # ⛏ Выбор миссии: сложность = редкость и уровень противника,
    # награда — осколки за ПОБЕДУ. Кулдаун MISSION_COOLDOWN_MIN — свой.
    fl = await db_get_flags(user_id)
    left = cooldown_left(await db_get_stamp(user_id, "last_mission_at"),
                         MISSION_COOLDOWN_MIN) if MISSION_COOLDOWN_MIN > 0 else 0
    if await db_load_battle(user_id):
        cd_line = "⚔️ Сначала завершите текущий бой/миссию."
    elif left > 0:
        cd_line = f"⏳ Следующая миссия — через <b>{fmt_left(left)}</b>."
    else:
        cd_line = "✅ Отряд готов к вылазке."
    lines = ["⛏ <b>Миссия по добыче осколков</b>",
             f"💎 Осколков: {fl.get('shards') or 0} · {cd_line}",
             "",
             "Отряд (ваша ⭐приоритетная колода, иначе первая непустая) уходит "
             "на вылазку: это обычный бой с ботом, но противник сильнее. "
             "Осколки — только за ПОБЕДУ:"]
    rows = []
    for m in MISSIONS:
        rows.append([ib(f"{m['label']} — враг {rarity_label(m['rar'])}"
                        + (f", +{m['dlvl']} ур." if m["dlvl"] else "")
                        + f" · 💎{m['shards']}", f"artmr:{m['key']}")])
    rows.append([ib("⬅️ Назад", "art:0")])
    return "\n".join(lines), InlineKeyboardMarkup(inline_keyboard=rows)


@router.callback_query(F.data == "artm")
async def cb_missions(call: CallbackQuery):
    if not await _art_ok(call):
        return
    text, markup = await missions_screen(call.from_user.id)
    await safe_answer(call)
    await safe_edit(call, text, markup)


def _mission_by_key(key: str):
    return next((x for x in MISSIONS if x["key"] == key), None)


async def _mission_preflight(uid: int):
    # Общие проверки перед миссией (выбор раскладки и старт): активный бой,
    # кулдаун, наличие колоды. Возвращает (текст_ошибки, None) или (None, карты).
    # Колода — ⭐приоритетная, иначе первая непустая (как в админ-прогоне).
    if await db_load_battle(uid):
        return "У вас уже идёт бой — сначала завершите его.", None
    if MISSION_COOLDOWN_MIN > 0:
        left = cooldown_left(await db_get_stamp(uid, "last_mission_at"),
                             MISSION_COOLDOWN_MIN)
        if left > 0:
            return f"⏳ Миссия доступна через {fmt_left(left)}.", None
    all_cards = await db_user_cards(uid)
    decks = decks_of(all_cards)
    pref = await user_flag(uid, "pref_deck")
    deck = pref if decks.get(pref) else next((d for d in sorted(decks) if decks[d]), 0)
    cards = decks.get(deck, [])[:MAX_DECK] if deck else []
    if not cards:
        return "Все колоды пусты — соберите колоду (🃏 Колода).", None
    return None, cards


@router.callback_query(F.data.startswith("artmr:"))
async def cb_mission_pick(call: CallbackQuery):
    # Выбрана миссия → выбор РАССТАНОВКИ (сколько клеток фронта и тыла —
    # те же 3 раскладки, что и в обычном бою: 3+1, 2+2, 1+3).
    if not await _art_ok(call):
        return
    key = call.data.split(":")[1]
    m = _mission_by_key(key)
    uid = call.from_user.id
    if m is None:
        await safe_answer(call, "Неизвестная миссия.", show_alert=True)
        return
    err, cards = await _mission_preflight(uid)
    if err:
        await safe_answer(call, err, show_alert=True)
        return
    await safe_answer(call)
    await safe_edit(call, f"⛏ <b>Миссия: {m['label']}</b>\n\n"
                          f"Отряд: {len(cards)} карт · противник: {rarity_label(m['rar'])}"
                          + (f", уровень +{m['dlvl']}" if m["dlvl"] else "")
                          + f" · награда за победу: 💎{m['shards']}\n\n"
                          "Выберите расстановку (<b>всего 4 клетки</b>, максимум 3 "
                          "на линию, обе линии обязательны — как в обычном бою):\n"
                          "• <b>3 фронта / 1 тыл</b> — фронт 1,2,3; тыл 2\n"
                          "• <b>2 фронта / 2 тыла</b> — обе линии: 1 и 3\n"
                          "• <b>1 фронт / 3 тыла</b> — фронт 2; тыл 1,2,3",
                    kb([ib("🛡 3 фронта / 1 тыл", f"artmgo:{key}:31")],
                       [ib("⚖️ 2 фронта / 2 тыла", f"artmgo:{key}:22")],
                       [ib("🏹 1 фронт / 3 тыла", f"artmgo:{key}:13")],
                       [ib("⬅️ Назад", "artm")]))


@router.callback_query(F.data.startswith("artmgo:"))
async def cb_mission_run(call: CallbackQuery):
    # Старт миссии с выбранной раскладкой: artmgo:{key}:{layout}. Обычный
    # бой движка с меткой state["mission"] — по победе end_battle начислит
    # осколки. Проверки (бой/кулдаун/колода) повторяются — кнопка могла
    # «дожить» с экрана, показанного до их срабатывания.
    if not await _art_ok(call):
        return
    parts = call.data.split(":")
    key = parts[1]
    layout_key = parts[2] if len(parts) > 2 else ""
    m = _mission_by_key(key)
    uid = call.from_user.id
    if m is None or layout_key not in LAYOUTS:
        await safe_answer(call, "Неизвестная миссия или раскладка.", show_alert=True)
        return
    err, cards = await _mission_preflight(uid)
    if err:
        await safe_answer(call, err, show_alert=True)
        return
    artifacts, skipped = apply_artifact_budget(
        cards, await equipped_artifact_bonuses(uid))
    avg_level = max(1, round(sum(c["level"] for c in cards) / len(cards)))
    state = create_battle(cards, layout_key,
                          enemy_rarity=m["rar"], enemy_level=avg_level + m["dlvl"],
                          artifacts=artifacts)
    state["mission"] = {"key": m["key"], "label": m["label"], "shards": m["shards"]}
    log_add(state, f"⛏ Миссия «{m['label']}» началась! Победа принесёт "
                   f"💎{m['shards']} осколков. Удачи!")
    if skipped:
        names = ", ".join(c["name"] for c in cards if c["id"] in skipped)
        log_add(state, f"🗡 Лимит силы отряда ({ART_DECK_POWER_LIMIT:g} п.): "
                       f"артефакты не вошли в бой — {names}.")
    await db_save_battle(uid, state)
    if MISSION_COOLDOWN_MIN > 0:
        await db_stamp(uid, "last_mission_at")   # кулдаун — от старта вылазки
    await safe_answer(call, "⛏ Отряд ушёл на вылазку!")
    await safe_edit(call, battle_text(state), kb_battle(state))


# =====================================================================
# АДМИН-ПАНЕЛЬ (/admin + пароль ADMIN_PASSWORD)
# Возможности (по заданию): получить карту (любой редкости), прокачать,
# сменить редкость, удалить, вылечить все карты и ПРОГОН БОЁВ:
# N сражений (N < 50) собранной колодой игрока против колоды
# АНАЛОГИЧНОЙ РЕДКОСТИ; полные логи ходов сохраняются в БД и
# отправляются игроку файлом.
# =====================================================================

ADMIN_PAGE = 8


def admin_text() -> str:
    return ("🛠 <b>Админ-панель</b>\n\n"
            "🎲 Выдать карту — любая редкость, сразу в колоду №1\n"
            "⬆️ Прокачать — +1/+5/+10 уровней или «до 10»; очки роста можно "
            "распределить вручную 🎯 или применить автоматически 🎲 "
            "(прокачка ничего не лечит и не восстанавливает)\n"
            "✨ Редкость — изменить грейд карты\n"
            "🗑 Удалить карту\n"
            "❤️ Вылечить все карты\n"
            f"⚔️ Прогон боёв — N боёв (N &lt; 50) вашей колодой против колоды "
            f"аналогичной редкости; полный лог ходов придёт файлом.\n"
            "🧪 Фичи — экспериментальные разделы (🗡 Артефакты, 🔴 Арканы): "
            "включаются только здесь и ИНДИВИДУАЛЬНО каждому игроку.")


def admin_kb() -> InlineKeyboardMarkup:
    return kb(
        [ib("🎲 Выдать карту", "adm:new"), ib("⬆️ Прокачать", "adm:lvl:0")],
        [ib("✨ Редкость", "adm:rar:0"), ib("🗑 Удалить", "adm:del:0")],
        [ib("❤️ Вылечить все карты", "adm:heal")],
        [ib("⚔️ Прогон боёв", "adm:sim")],
        [ib("🧪 Фичи (Артефакты/Арканы)", "adm:feat")],
        [ib("🏠 Меню", "mn:home")],
    )


# ---------- 🧪 экспериментальные фичи: индивидуальное включение ----------

FEAT_COLS = {"art": ("feat_artifacts", "🗡 Артефакты и миссии"),
             "arc": ("feat_arcana", "🔴 Аркановые персонажи")}


async def feat_screen(target_uid: int):
    # Экран флагов игрока target_uid: что включено + тумблеры
    fl = await db_get_flags(target_uid)
    lines = [f"🧪 <b>Экспериментальные фичи</b> · игрок <code>{target_uid}</code>", ""]
    rows = []
    for key, (col, label) in FEAT_COLS.items():
        on = bool(fl.get(col))
        lines.append(f"{label}: {'✅ ВКЛЮЧЕНО' if on else '❌ выключено'}")
        rows.append([ib(f"{'🚫 Выключить' if on else '✅ Включить'} — {label}",
                        f"admf:{target_uid}:{key}")])
    lines += ["", "🗡 Артефакты: у игрока в «👤 Профиль» появляется раздел "
                 "артефактов и миссии по добыче 💎.",
              "🔴 Арканы: новые карты игрока с шансом ARCANA_CHANCE_PCT% "
              "становятся АРКАНОВОЙ редкости (статы как у легендарной) и "
              "принадлежат сету — связки на поле дают ауры."]
    rows.append([ib("⬅️ Админ-панель", "adm:root")])
    return "\n".join(lines), InlineKeyboardMarkup(inline_keyboard=rows)


async def admin_card_list(call: CallbackQuery, op: str, page: int):
    # Список карт для админ-операций (прокачка/редкость/удаление)
    uid = call.from_user.id
    cards = await db_user_cards(uid)
    titles = {"lvl": "⬆️ Прокачать — выберите карту:",
              "rar": "✨ Смена редкости — выберите карту:",
              "del": "🗑 Удаление — выберите карту:"}
    if not cards:
        await safe_answer(call)
        await safe_edit(call, "Карт нет. Выдайте их кнопкой «🎲 Выдать карту».",
                        kb([ib("🎲 Выдать карту", "adm:new")], [ib("🛠 Панель", "adm:root")]))
        return
    n_pages = (len(cards) + ADMIN_PAGE - 1) // ADMIN_PAGE
    page = max(0, min(page, n_pages - 1))
    chunk = cards[page * ADMIN_PAGE:(page + 1) * ADMIN_PAGE]
    rows = []
    for c in chunk:
        rem = rarity_label(c["rarity"] if "rarity" in c.keys() else "common").split(" ")[0]
        rows.append([ib(f"{rem}{CLS_EMOJI[c['cls']]} {c['name']} {c['surname']} · L{c['level']}",
                        f"adm:{op}:pick:{c['id']}")])
    nav = []
    if page > 0:
        nav.append(ib("◀️", f"adm:{op}:{page - 1}"))
    nav.append(ib("🛠 Панель", "adm:root"))
    if page < n_pages - 1:
        nav.append(ib("▶️", f"adm:{op}:{page + 1}"))
    rows.append(nav)
    await safe_answer(call)
    await safe_edit(call, titles[op], InlineKeyboardMarkup(inline_keyboard=rows))


async def run_battle_sims(user_id: int, n: int):
    # Прогон N боёв: колода игрока против сгенерированной колоды АНАЛОГИЧНОЙ
    # РЕДКОСТИ (средний ранг редкости и средний уровень колоды игрока).
    # Оба игрока — движковый ИИ. Колода: ⭐приоритетная, иначе первая
    # непустая (№1→№2→№3). Возвращает (summary, full_log) или (None, None).
    all_cards = await db_user_cards(user_id)
    decks = decks_of(all_cards)
    pref = await user_flag(user_id, "pref_deck")
    deck = pref if decks.get(pref) else next((d for d in sorted(decks) if decks[d]), 1)
    bcards = await db_battle_cards(user_id, deck)
    if not bcards:
        return None, None
    # 🗡 Если игроку включены артефакты — прогон учитывает надетые
    # (в пределах лимита силы отряда — симуляция совпадает с реальным боем).
    artifacts = None
    if await user_flag(user_id, "feat_artifacts"):
        artifacts, _skipped = apply_artifact_budget(
            bcards, await equipped_artifact_bonuses(user_id))
    n = max(1, min(n, SIM_MAX_BATTLES))
    ranks = [rarity_rank(c["rarity"] if "rarity" in c.keys() else "common") for c in bcards]
    enemy_rarity = RARITY_KEYS[max(0, min(4, round(sum(ranks) / len(ranks))))]
    avg_level = max(1, round(sum(c["level"] for c in bcards) / len(bcards)))
    deck_desc = ", ".join(
        f"{c['name']} {c['surname']} ({rarity_label(c['rarity'] if 'rarity' in c.keys() else 'common')}, "
        f"L{c['level']}, {CLS_NAME[c['cls']]})" for c in bcards)
    results = {"victory": 0, "defeat": 0, "draw": 0}
    rounds_total = 0
    spells_cast = 0
    full_log = [
        "⚔️ ПРОГОН БОЁВ (админ-панель)",
        f"Боёв: {n} · Колода игрока №{deck}: {deck_desc}",
        f"Противник: колода аналогичной редкости ({rarity_label(enemy_rarity)}), средний уровень {avg_level}",
        "",
    ]
    for i in range(n):
        state = create_battle([dict(c) for c in bcards],
                              random.choice(list(LAYOUTS)), enemy_rarity=enemy_rarity,
                              artifacts=artifacts)
        state["no_trim"] = True  # полный журнал без обрезки
        seen = 0
        battle_log = [f"=== БОЙ {i + 1}/{n} ==="]
        side = "player"
        it = 0
        while not state["over"] and it < 3000:
            begin_turn(state, side)
            if check_over(state):
                break
            ai_act(state, side)
            check_over(state)
            new_lines = state["log"][seen:]
            seen = len(state["log"])
            who = "ВЫ " if side == "player" else "ВРАГ"
            battle_log += [f"[Р{state['round']}·{who}] {l}" for l in new_lines]
            side = other_side(side)
            if side == "player":
                state["round"] += 1   # раунд = полный круг (ваш ход + ход противника)
            it += 1
        res = state["result"] or "draw"
        results[res] = results.get(res, 0) + 1
        rounds_total += state["round"]
        spells_cast += sum(1 for l in state["log"] if "кастует" in l)
        battle_log.append(f"--- ИТОГ БОЯ {i + 1}: {res.upper()}, раундов: {state['round']} ---")
        full_log += battle_log + [""]
    winrate = results["victory"] * 100 // max(1, n)
    summary = (f"⚔️ <b>Прогон: {n} боёв</b> · колода №{deck}\n"
               f"🏆 Побед: {results['victory']} ({winrate}%) · ☠️ Поражений: {results['defeat']} · "
               f"🤝 Ничьих: {results['draw']}\n"
               f"⏱ Средняя длина боя: {rounds_total // max(1, n)} раундов · "
               f"✨ Заклинаний скастовано: {spells_cast}\n"
               f"Противник: {rarity_label(enemy_rarity)}, средний уровень {avg_level}.")
    return summary, "\n".join(full_log)


@router.callback_query(F.data.startswith("adm:"))
async def cb_admin(call: CallbackQuery, bot: Bot):
    uid = call.from_user.id
    if not await user_flag(uid, "is_admin"):
        await safe_answer(call, "Нужен админ-доступ: отправьте /admin.", show_alert=True)
        return
    parts = call.data.split(":")
    op = parts[1]

    if op == "root":
        await safe_answer(call)
        await safe_edit(call, admin_text(), admin_kb())
        return

    if op == "new":
        if len(parts) == 2:
            rows = [[ib("🎰 Случайная редкость", "adm:new:rand")]]
            rows += [[ib(rarity_label(k), f"adm:new:{k}")] for k in RARITY_KEYS]
            rows.append([ib("⬅️ Назад", "adm:root")])
            await safe_answer(call)
            await safe_edit(call, "🎲 <b>Выдача карты</b> — выберите редкость:",
                            InlineKeyboardMarkup(inline_keyboard=rows))
        else:
            r = None if parts[2] == "rand" else parts[2]
            d = generate_card_data(rarity=r)
            cid = await db_add_card(uid, d)
            await db_set_in_deck(cid, deck_bit(1))  # админская карта сразу в колоде №1
            row = await db_get_card(cid, uid)
            await safe_answer(call, "Карта выдана ✅")
            await safe_edit(call, "🎲 <b>Карта выдана</b> (сразу добавлена в колоду №1 "
                                  "— при желании переложите в «🃏 Колода»):\n\n" + card_text(row),
                            kb([ib("🎲 Выдать ещё", "adm:new")], [ib("🛠 Панель", "adm:root")]))
        return

    if op == "heal":
        await db_admin_heal_all(uid)
        await safe_answer(call, "❤️ Все карты вылечены")
        await safe_edit(call, admin_text(), admin_kb())
        return

    if op in ("lvl", "rar", "del"):
        if len(parts) == 3 and parts[2].isdigit():
            await admin_card_list(call, op, int(parts[2]))
            return
        if parts[2] == "pick":
            cid = int(parts[3])
            row = await db_get_card(cid, uid)
            if not row:
                await safe_answer(call, "Карта не найдена.", show_alert=True)
                return
            if op == "lvl":
                markup = kb([ib("+1 уровень", f"adm:lvl:up:{cid}:1"), ib("+5 уровней", f"adm:lvl:up:{cid}:5")],
                            [ib("+10 уровней", f"adm:lvl:up:{cid}:10"), ib("⭐ До 10 уровня", f"adm:lvl:set:{cid}:10")],
                            [ib("⬅️ Назад", "adm:lvl:0")])
                await safe_answer(call)
                await safe_edit(call, "⬆️ <b>Прокачка карты</b>\n\n" + card_text(row), markup)
            elif op == "rar":
                rows = [[ib(rarity_label(k), f"adm:rar:set:{cid}:{k}")] for k in RARITY_KEYS]
                rows.append([ib("⬅️ Назад", "adm:rar:0")])
                await safe_answer(call)
                await safe_edit(call, "✨ <b>Смена редкости</b>\n\n" + card_text(row),
                                InlineKeyboardMarkup(inline_keyboard=rows))
            else:
                await safe_answer(call)
                await safe_edit(call, "🗑 <b>Удалить карту навсегда?</b>\n\n" + card_text(row),
                                kb([ib("✅ Удалить", f"adm:del:yes:{cid}")], [ib("⬅️ Назад", "adm:del:0")]))
            return
        if op == "lvl" and parts[2] in ("up", "set"):
            cid, n = int(parts[3]), int(parts[4])
            row = await db_get_card(cid, uid)
            if not row:
                await safe_answer(call, "Карта не найдена.", show_alert=True)
                return
            # Сколько уровней предстоит получить
            cnt = n if parts[2] == "up" else max(0, n - row["level"])
            if cnt <= 0:
                await safe_answer(call, f"Уровень уже {row['level']} — повышать нечего.",
                                  show_alert=True)
                return
            await safe_answer(call)
            await safe_edit(call, f"⬆️ <b>Прокачка: +{cnt} уровней</b>\n\n" + card_text(row) +
                            "\n\nКак применить рост?\n"
                            "🎯 <b>Вручную</b> — каждое очко = +1 уровень и +1 к выбранной "
                            "стате (как в бою, можно прерваться в любой момент).\n"
                            "🎲 <b>Авто</b> — стандартный рост за уровень.",
                            kb([ib("🎯 Распределить очки вручную", f"lvlm:{cid}:{cnt}")],
                               [ib("🎲 Автоматический рост", f"lvla:{cid}:{cnt}")],
                               [ib("⬅️ Назад", f"adm:lvl:pick:{cid}")]))
            return
        if op == "rar" and parts[2] == "set":
            cid, key = int(parts[3]), parts[4]
            if key in RARITY_INFO:
                await db_set_rarity(cid, key, uid)
            row = await db_get_card(cid, uid)
            await safe_answer(call, "✨ Редкость изменена")
            await safe_edit(call, card_text(row),
                            kb([ib("✨ Изменить ещё", f"adm:rar:pick:{cid}")], [ib("🛠 Панель", "adm:root")]))
            return
        if op == "del" and parts[2] == "yes":
            cid = int(parts[3])
            await db_delete_card(cid, uid)
            await safe_answer(call, "🗑 Карта удалена")
            cards_left = await db_user_cards(uid)
            if cards_left:
                await admin_card_list(call, "del", 0)
            else:
                await safe_edit(call, admin_text(), admin_kb())
            return

    if op == "feat":
        # 🧪 Экспериментальные фичи — индивидуальное включение игрокам.
        # adm:feat — выбор: себе или по ID; adm:feat:u:{uid} — экран флагов.
        if len(parts) == 2:
            rows = [[ib("🧪 Включить/выключить СЕБЕ", f"adm:feat:u:{uid}")],
                    [ib("👤 Другому игроку (по ID)", "adm:feat:ask")],
                    [ib("⬅️ Назад", "adm:root")]]
            await safe_answer(call)
            await safe_edit(call, "🧪 <b>Экспериментальные фичи</b>\n\n"
                                   "🗡 Артефакты и 🌀 Арканы выключены у всех по "
                                   "умолчанию и включаются ИНДИВИДУАЛЬНО: себе — "
                                   "сразу, другому игроку — по его Telegram ID "
                                   "(числовой; узнать: «👤 Профиль» игрока не "
                                   "показывает ID — спросите у самого игрока или "
                                   "посмотрите в таблице users).",
                            InlineKeyboardMarkup(inline_keyboard=rows))
            return
        if parts[2] == "ask":
            await set_user_flag(uid, "awaiting_feat", 1)
            await safe_answer(call)
            await safe_edit(call, "👤 Отправьте <b>числовой Telegram ID</b> игрока "
                                  "обычным сообщением — откроется экран его фич.\n"
                                  "Для отмены — /cancel.",
                            kb([ib("⬅️ Отменить", "adm:feat")]))
            return
        if parts[2] == "u":
            target = int(parts[3])
            await ensure_user_row(target)   # игрок может ещё не писать боту
            text, markup = await feat_screen(target)
            await safe_answer(call)
            await safe_edit(call, text, markup)
            return

    if op == "sim":
        if len(parts) == 2:
            ns = sorted({5, 10, 25, SIM_MAX_BATTLES})
            rows = [[ib(f"⚔️ Прогнать {x} боёв", f"adm:sim:run:{x}")] for x in ns if x < 50]
            rows.append([ib("⬅️ Назад", "adm:root")])
            await safe_answer(call)
            await safe_edit(call, "⚔️ <b>Прогон боёв</b> (N &lt; 50):\nВаша боевая колода против "
                                   "колоды аналогичной редкости. Полный лог ходов придёт файлом.",
                            InlineKeyboardMarkup(inline_keyboard=rows))
            return
        if parts[2] == "run":
            n = min(int(parts[3]), SIM_MAX_BATTLES)
            await safe_answer(call, f"⚔️ Прогоняю {n} боёв, пару секунд…")
            summary, log_text = await run_battle_sims(uid, n)
            if summary is None:
                await safe_edit(call, "⚔️ Боевая колода пуста — сначала соберите колоду (🃏 Колода → 📥 В колоду).",
                                kb([ib("🛠 Панель", "adm:root")]))
                return
            sim_id = await db_save_sim(uid, n, summary, log_text)
            path = os.path.join(tempfile.gettempdir(), f"sim_{uid}_{sim_id}.txt")
            with open(path, "w", encoding="utf-8") as fh:
                fh.write(log_text)
            doc = FSInputFile(path, filename=f"sim_{n}_battles.txt")
            try:
                await bot.send_document(uid, doc, caption=summary.replace("<b>", "").replace("</b>", ""))
            finally:
                if os.path.exists(path):
                    os.unlink(path)
            await safe_edit(call, summary + f"\n\n📄 Полный лог отправлен файлом и сохранён в БД (запись #{sim_id}).",
                            kb([ib("⚔️ Прогнать ещё", "adm:sim")], [ib("🛠 Панель", "adm:root")]))
            return

    await safe_answer(call)
    await safe_edit(call, admin_text(), admin_kb())


# =====================================================================
# АДМИН-ПРОКАЧКА С РАСПРЕДЕЛЕНИЕМ ОЧКОВ (заказ Richard Quant):
# каждое очко = +1 уровень и +1 к выбранной стате — как в боевом потоке
# «🌟 Уровень!». Состояние не храним: остаток очков живёт в callback
# (lvlm:{cid}:{осталось}[:{стата}]) — для serverless это безопасно.
# =====================================================================

async def _admin_ok(call: CallbackQuery) -> bool:
    # Страж админ-доступа для отдельных админ-хендлеров
    if not await user_flag(call.from_user.id, "is_admin"):
        await safe_answer(call, "Нужен админ-доступ: отправьте /admin.", show_alert=True)
        return False
    return True


async def _admin_lvl_final(call: CallbackQuery, row, head: str):
    # Финальный экран прокачки: карточка + «ещё»/«панель»
    await safe_edit(call, head + card_text(row),
                    kb([ib("⬆️ Прокачать ещё", f"adm:lvl:pick:{row['id']}")],
                       [ib("🛠 Панель", "adm:root")]))


@router.callback_query(F.data.startswith("lvlm:"))
async def cb_admin_lvl_manual(call: CallbackQuery):
    # Ручное распределение: lvlm:{cid}:{осталось очков}[:{стата}]
    if not await _admin_ok(call):
        return
    parts = call.data.split(":")
    cid, cnt = int(parts[1]), int(parts[2])
    stat = parts[3] if len(parts) > 3 else None
    uid = call.from_user.id
    row = await db_get_card(cid, uid)
    if not row:
        await safe_answer(call, "Карта не найдена.", show_alert=True)
        return
    if stat:
        if stat not in stat_choices_for(row):
            await safe_answer(call, "Эта стата недоступна для класса карты.", show_alert=True)
            return
        await db_admin_set_stats(cid, apply_card_stat_choice(row, stat))
        row = await db_get_card(cid, uid)
        cnt -= 1
        await safe_answer(call, f"⬆️ L{row['level']} — очко вложено")
        if cnt <= 0:
            await _admin_lvl_final(call, row, "✅ <b>Прокачка завершена</b> — "
                                              "все очки распределены.\n\n")
            return
    else:
        await safe_answer(call)
    text = (f"⬆️ <b>Прокачка: распределение очков</b>\n\n"
            f"Осталось вложить: <b>{cnt}</b> (каждое очко = +1 уровень и +1 стата).\n\n"
            + card_text(row))
    rows = []
    for st in stat_choices_for(row):
        lbl = sub_choice_label(row) if st == "sub" else ADMIN_STAT_LABEL[st]
        rows.append([ib(lbl, f"lvlm:{cid}:{cnt}:{st}")])
    rows.append([ib("⏭ Завершить (остаток не вкладывать)", f"lvlfin:{cid}")])
    rows.append([ib("🛠 Панель", "adm:root")])
    await safe_edit(call, text, InlineKeyboardMarkup(inline_keyboard=rows))


@router.callback_query(F.data.startswith("lvla:"))
async def cb_admin_lvl_auto(call: CallbackQuery):
    # Автоматическая прокачка (как раньше): apply_level_growth за уровень.
    # БЕЗ лечения: текущее hp сохраняется как есть (все восстановления
    # при прокачке убраны по заказу).
    if not await _admin_ok(call):
        return
    parts = call.data.split(":")
    cid, cnt = int(parts[1]), int(parts[2])
    uid = call.from_user.id
    row = await db_get_card(cid, uid)
    if not row:
        await safe_answer(call, "Карта не найдена.", show_alert=True)
        return
    d = {"level": row["level"], "attack": row["attack"], "armor": row["armor"],
         "hp": row["hp"], "hp_max": row["hp_max"], "sub": row["sub"],
         "mana_max": row["mana_max"], "end_max": row["end_max"], "cls": row["cls"]}
    for _ in range(cnt):
        apply_level_growth(d)
    await db_admin_set_stats(cid, d)
    row = await db_get_card(cid, uid)
    await safe_answer(call, "⬆️ Прокачано (авто)")
    await _admin_lvl_final(call, row, "")


@router.callback_query(F.data.startswith("lvlfin:"))
async def cb_admin_lvl_finish(call: CallbackQuery):
    # Досрочное завершение распределения: уже вложенные уровни остаются,
    # остаток очков просто не применяется.
    if not await _admin_ok(call):
        return
    cid = int(call.data.split(":")[1])
    row = await db_get_card(cid, call.from_user.id)
    await safe_answer(call, "Распределение завершено")
    if not row:
        await safe_edit(call, "Карта не найдена.", kb([ib("🛠 Панель", "adm:root")]))
        return
    await _admin_lvl_final(call, row, "⏹ <b>Распределение завершено досрочно.</b>\n\n")


@router.callback_query(F.data.startswith("admf:"))
async def cb_admin_feat_toggle(call: CallbackQuery):
    # 🧪 Тумблер фичи: admf:{target_uid}:{art|arc} — включить/выключить
    # раздел выбранному игроку (индивидуально, по заказу).
    if not await _admin_ok(call):
        return
    parts = call.data.split(":")
    target, key = int(parts[1]), parts[2]
    if key not in FEAT_COLS:
        await safe_answer(call, "Неизвестная фича.", show_alert=True)
        return
    col, label = FEAT_COLS[key]
    await ensure_user_row(target)
    cur = await user_flag(target, col)
    await set_user_flag(target, col, 0 if cur else 1)
    await safe_answer(call, f"{label}: {'выключено' if cur else 'включено'} "
                            f"игроку {target}")
    text, markup = await feat_screen(target)
    await safe_edit(call, text, markup)


